<template>

  <div
    ref="mainWrapper"
    class="main-wrapper"
    :style="mainWrapperStyles"
  >
    <div class="scrolling-pane">
      <CoreBanner v-if="coreBannerComponent && showDemoBanner">
        <template #default="props">
          <component
            :is="coreBannerComponent"
            :bannerClosed="props.bannerClosed"
          />
        </template>
      </CoreBanner>

      <KPageContainer v-if="!isAuthorized">
        <AuthMessage />
      </KPageContainer>
      <KPageContainer v-else-if="error">
        <AppError />
      </KPageContainer>

      <div
        v-else
        role="main"
        tabindex="-1"
        class="main"
      >
        <h1
          v-if="pageHeading"
          class="visuallyhidden"
        >
          {{ pageHeading }}
        </h1>
        <slot></slot>
      </div>
    </div>

    <!-- Monitor snackbar changes so they can be announced by assistive technologies -->
    <div aria-live="polite">
      <GlobalSnackbar />
    </div>
  </div>

</template>


<script>

  import get from 'lodash/get';
  import AuthMessage from 'kolibri/components/AuthMessage';
  import AppError from 'kolibri/components/error/AppError';
  import GlobalSnackbar from 'kolibri/components/GlobalSnackbar';
  import { pageHeading } from 'kolibri/composables/usePageTitle';
  import { error } from 'kolibri/utils/appError';
  import { ComponentMap } from '../constants';
  import CoreBanner from './CoreBanner';

  export default {
    name: 'UserAuthLayout',
    components: {
      AppError,
      CoreBanner,
      AuthMessage,
      GlobalSnackbar,
    },
    setup() {
      return { error, pageHeading };
    },
    computed: {
      isAuthorized() {
        return !(
          this.error &&
          this.error.response &&
          this.error.response.status &&
          this.error.response.status == 403
        );
      },
      mainWrapperStyles() {
        return {
          width: '100vw',
          backgroundColor: 'var(--palette-grey-v200)',
          paddingTop: '0px',
          paddingBottom: '0px',
        };
      },
      coreBannerComponent() {
        return get(window, ['_coreBannerContent', '0']);
      },
      showDemoBanner() {
        return [
          ComponentMap.USERNAME_SIGN_IN,
          ComponentMap.PICTURE_SIGN_IN,
          ComponentMap.FACILITY_SELECT,
          ComponentMap.AUTH_SELECT,
          ComponentMap.NEW_PASSWORD,
        ].includes(this.$route.name);
      },
    },
  };

</script>


<style lang="scss" scoped>

  .main-wrapper {
    display: inline-block;
    width: 100vw;

    @media print {
      /* Without this, things won't print correctly
    *  - Firefox: Tables will get cutoff
    *  - Chrome: Table header won't repeat correctly on each page
    */
      display: block;
    }
  }

  .main {
    height: 100%;
    margin-right: auto;
    margin-left: auto;
  }

  .scrolling-pane {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    padding: 0;
    margin-top: 0;
    margin-bottom: 0;
    overflow-x: auto;
  }

  .debug {
    font-family: monospace;
